import{j as s,P as m,t as u,x as n,L as g}from"./index-CN8REocs.js";const e={name:"Unlag",email:"unlagpcoptimizer@gmail.com"},l="Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723, USA (vercel.com)",h="2026-11-03",c="Premium 14,99 €, Ultimate 29,99 €",f={en:{terms:{title:"Terms of service",lead:"The rules for using Unlag, the app, this site and your account.",sections:[["1. Who we are",[`Unlag is the publisher of the Unlag app and of this site. Contact: ${e.email}.`]],["2. What Unlag is",["Unlag is a Windows 10 and 11 application that changes system settings (registry, services, power plans, drivers and, on compatible motherboards, firmware settings) to reduce latency and clean up Windows. This site lets you download the app and manage your account and plan."]],["3. Accepting these terms",["By creating an account, installing or using Unlag, you accept these terms. If you do not accept them, do not use Unlag. You must be at least 15 years old, or have the permission of a parent or guardian."]],["4. Your account",["You need an account to use the app. You keep your sign-in details secret and you are responsible for what happens with your account. Turn on two-step sign-in in Account settings for extra protection. Tell us right away if you think someone else uses your account."]],["5. Plans and prices",[`The Free plan costs nothing. Paid plans are a one-time payment, taxes included: ${c}. A paid plan works on one PC, recognized by its hardware, and a PC holds the plan of one account only. If you change PC, contact us and we will move the plan once when the request is reasonable. Prices can change; a change never affects a plan you already bought.`]],["6. Right of withdrawal",["A paid plan is digital content supplied right away. When you buy it, you ask for it to be supplied immediately and you accept that you lose your 14-day right of withdrawal once the plan is active (article L221-28 13° of the French Consumer Code). If a paid feature does not work on your PC and we cannot fix it, contact us within 14 days and we will refund you."]],["7. Using the software",["We give you a personal, non-exclusive and non-transferable right to use Unlag. You must not copy, resell, decompile or modify the app, bypass its plan and PC checks, or use it to harm others. The assistant must not be used to generate abusive content."]],["8. Changes to your system",["Unlag changes Windows with administrator rights. Before each tweak it saves the original values so you can undo it, and it can create Windows restore points. Create one before your first changes. Each tweak shows its risk level: you choose what you apply. The BIOS module writes firmware settings: only use it if you understand them, and note your current settings first."]],["9. The assistant",["The assistant suggests tweaks from your hardware. Its answers can be wrong: check them before acting. Messages are processed by Google Gemini with your own API key."]],["10. Liability",["Unlag is provided as it is. As far as the law allows, we are not liable for indirect damage, loss of data, loss of games or matches, or damage caused by settings you chose to apply, in particular firmware settings. Nothing in these terms limits your rights as a consumer or our liability for gross negligence or intentional fault."]],["11. Updates and availability",["The app updates itself from our official releases. We can change, improve or stop features. We do our best to keep accounts available but do not guarantee uninterrupted service."]],["12. Suspension",["We can suspend or close an account that breaks these terms, in particular to bypass plan checks, share a paid plan or abuse the service. You can stop using Unlag and ask for your account to be deleted at any time."]],["13. Changes to these terms",["We can update these terms. The date at the top shows the last version. Important changes are announced on the site or by email."]],["14. Law and disputes",[`These terms are governed by French law. Contact us first at ${e.email}. Otherwise, the competent French courts have jurisdiction.`]]]},privacy:{title:"Privacy policy",lead:"What we collect, why, and how to control it.",sections:[["1. Who is responsible",[`The data controller is ${e.name}. For any question about your data: ${e.email}.`]],["2. What we collect",["Account: email address, display name, sign-in method, and the name and profile photo address sent by Google or Discord if you use them.","Plan: your plan and, for paid plans, a fingerprint of your PC (a SHA-256 hash computed from hardware identifiers). It cannot be turned back into the identifiers.","Usage: the number of assistant messages you sent today, and the reviews you send (rating, comment, app version).","Security: sign-in dates, IP address and browser type, recorded by our authentication provider to protect accounts."]],["3. What stays on your PC",["Your app settings, the backups of the values changed by tweaks, your assistant conversations and your Gemini key (encrypted with Windows) stay on your PC. We never receive them."]],["4. Why we use it",["To create and secure your account (contract), to give you the plan you paid for and link it to one PC (contract), to count assistant messages and prevent abuse (legitimate interest), and to send sign-in emails and codes (contract). We do not sell your data and we do not send advertising."]],["5. Who processes it",["Supabase (accounts and database), Vercel (site hosting), Resend (emails), Cloudflare Turnstile (bot protection on site forms), GitHub (app downloads and updates), Google and Discord (only if you sign in with them), Google Gemini (assistant messages, with your own key).","Some of these providers are located outside the European Union. Transfers are covered by the European Commission standard contractual clauses or an adequacy decision."]],["6. How long we keep it",["Account, plan and reviews: as long as your account exists. Assistant counters: a few days. Security logs: according to our authentication provider, usually a few weeks. When you delete your account, your data is deleted within 30 days, except what the law requires us to keep (for example invoices)."]],["7. Your rights",[`You can access, correct, delete or export your data, object to or restrict its use. Write to ${e.email}. You can also file a complaint with the CNIL (cnil.fr). You can change your display name and password yourself in Account settings.`]],["8. Cookies and storage",["We do not use advertising or analytics cookies. The site stores your session and your language choice in your browser. Cloudflare Turnstile may use strictly necessary data to tell people from bots."]],["9. Security",["Connections are encrypted, passwords are never stored in clear, and you can turn on two-step sign-in. On your PC, your session is encrypted with your Windows account."]]]},legal:{title:"Legal notice",lead:"Who publishes this site and who hosts it.",sections:[["Publisher",[e.name,`Email: ${e.email}`]],["Hosting",[l]],["Intellectual property",["The Unlag name, logo, app, site and texts belong to their publisher. Any reproduction without permission is forbidden. Windows is a trademark of Microsoft Corporation; NVIDIA, AMD, Intel, Google and Discord belong to their owners. Unlag is not affiliated with them."]],["Personal data",[]]]}},fr:{terms:{title:"Conditions générales d'utilisation et de vente",lead:"Les règles d'utilisation d'Unlag, de l'application, de ce site et de votre compte.",sections:[["1. Qui sommes-nous",[`Unlag édite l'application Unlag et ce site. Contact : ${e.email}.`]],["2. Ce qu'est Unlag",["Unlag est une application pour Windows 10 et 11 qui modifie des réglages du système (registre, services, plans d'alimentation, pilotes et, sur les cartes mères compatibles, réglages du firmware) pour réduire la latence et alléger Windows. Ce site permet de télécharger l'application et de gérer votre compte et votre offre."]],["3. Acceptation",["En créant un compte, en installant ou en utilisant Unlag, vous acceptez ces conditions. Si vous ne les acceptez pas, n'utilisez pas Unlag. Vous devez avoir au moins 15 ans, ou l'accord d'un parent ou tuteur."]],["4. Votre compte",["Un compte est nécessaire pour utiliser l'application. Vous gardez vos identifiants secrets et vous êtes responsable de ce qui est fait avec votre compte. Activez la connexion en deux étapes dans les réglages du compte pour plus de sécurité. Prévenez-nous immédiatement si vous pensez qu'un tiers utilise votre compte."]],["5. Offres et prix",[`L'offre Free est gratuite. Les offres payantes sont un paiement unique, toutes taxes comprises : ${c}. Une offre payante fonctionne sur un seul PC, reconnu par son matériel, et un PC ne porte l'offre que d'un seul compte. Si vous changez de PC, contactez-nous : nous transférons l'offre une fois lorsque la demande est raisonnable. Les prix peuvent évoluer, sans effet sur une offre déjà achetée.`]],["6. Droit de rétractation",["Une offre payante est un contenu numérique fourni immédiatement. En l'achetant, vous demandez son exécution immédiate et reconnaissez perdre votre droit de rétractation de 14 jours dès que l'offre est active (article L221-28 13° du Code de la consommation). Si une fonction payante ne marche pas sur votre PC et que nous ne pouvons pas la corriger, contactez-nous sous 14 jours : nous vous remboursons."]],["7. Utilisation du logiciel",["Nous vous accordons un droit d'utilisation personnel, non exclusif et non transférable. Il est interdit de copier, revendre, décompiler ou modifier l'application, de contourner ses vérifications d'offre et de PC, ou de l'utiliser pour nuire à autrui. L'assistant ne doit pas servir à produire des contenus abusifs."]],["8. Modifications de votre système",["Unlag modifie Windows avec les droits administrateur. Avant chaque réglage, il enregistre les valeurs d'origine pour pouvoir l'annuler, et il peut créer des points de restauration Windows. Créez-en un avant vos premières modifications. Chaque réglage affiche son niveau de risque : vous choisissez ce que vous appliquez. Le module BIOS écrit des réglages du firmware : utilisez-le seulement si vous les comprenez, et notez vos réglages actuels avant."]],["9. L'assistant",["L'assistant propose des réglages à partir de votre matériel. Ses réponses peuvent être fausses : vérifiez-les avant d'agir. Les messages sont traités par Google Gemini avec votre propre clé API."]],["10. Responsabilité",["Unlag est fourni en l'état. Dans les limites permises par la loi, nous ne sommes pas responsables des dommages indirects, des pertes de données, de parties ou de matchs, ni des dommages causés par des réglages que vous avez choisi d'appliquer, en particulier ceux du firmware. Rien dans ces conditions ne limite vos droits de consommateur ni notre responsabilité en cas de faute lourde ou intentionnelle."]],["11. Mises à jour et disponibilité",["L'application se met à jour depuis nos versions officielles. Nous pouvons modifier, améliorer ou arrêter des fonctions. Nous faisons notre possible pour que les comptes restent disponibles, sans garantir un service ininterrompu."]],["12. Suspension",["Nous pouvons suspendre ou fermer un compte qui ne respecte pas ces conditions, notamment pour contourner les vérifications d'offre, partager une offre payante ou abuser du service. Vous pouvez arrêter d'utiliser Unlag et demander la suppression de votre compte à tout moment."]],["13. Modification des conditions",["Nous pouvons mettre à jour ces conditions. La date en haut indique la dernière version. Les changements importants sont annoncés sur le site ou par email."]],["14. Droit applicable et litiges",[`Ces conditions sont soumises au droit français. Contactez-nous d'abord à ${e.email}. À défaut, les tribunaux français compétents sont seuls compétents.`]]]},privacy:{title:"Politique de confidentialité",lead:"Ce que nous collectons, pourquoi, et comment le contrôler.",sections:[["1. Responsable du traitement",[`Le responsable du traitement est ${e.name}. Pour toute question sur vos données : ${e.email}.`]],["2. Données collectées",["Compte : adresse email, nom d'affichage, méthode de connexion, ainsi que le nom et l'adresse de la photo de profil transmis par Google ou Discord si vous les utilisez.","Offre : votre offre et, pour les offres payantes, une empreinte de votre PC (un hachage SHA-256 calculé à partir d'identifiants matériels). Elle ne permet pas de retrouver ces identifiants.","Utilisation : le nombre de messages envoyés à l'assistant aujourd'hui, et les avis que vous envoyez (note, commentaire, version de l'application).","Sécurité : dates de connexion, adresse IP et type de navigateur, enregistrés par notre fournisseur d'authentification pour protéger les comptes."]],["3. Ce qui reste sur votre PC",["Les réglages de l'application, les sauvegardes des valeurs modifiées par les réglages, vos conversations avec l'assistant et votre clé Gemini (chiffrée par Windows) restent sur votre PC. Nous ne les recevons jamais."]],["4. Finalités et bases légales",["Créer et sécuriser votre compte (contrat), vous fournir l'offre achetée et la lier à un PC (contrat), compter les messages de l'assistant et empêcher les abus (intérêt légitime), envoyer les emails et codes de connexion (contrat). Nous ne vendons pas vos données et n'envoyons pas de publicité."]],["5. Destinataires et sous-traitants",["Supabase (comptes et base de données), Vercel (hébergement du site), Resend (emails), Cloudflare Turnstile (protection anti-robots des formulaires), GitHub (téléchargements et mises à jour), Google et Discord (seulement si vous vous connectez avec eux), Google Gemini (messages de l'assistant, avec votre propre clé).","Certains de ces prestataires sont situés hors de l'Union européenne. Les transferts sont encadrés par les clauses contractuelles types de la Commission européenne ou une décision d'adéquation."]],["6. Durée de conservation",["Compte, offre et avis : tant que votre compte existe. Compteurs de l'assistant : quelques jours. Journaux de sécurité : selon notre fournisseur d'authentification, en général quelques semaines. À la suppression du compte, vos données sont effacées sous 30 jours, sauf ce que la loi nous oblige à conserver (par exemple les factures)."]],["7. Vos droits",[`Vous pouvez accéder à vos données, les rectifier, les effacer, les exporter, vous opposer à leur traitement ou le limiter. Écrivez à ${e.email}. Vous pouvez aussi adresser une réclamation à la CNIL (cnil.fr). Vous pouvez modifier vous-même votre nom d'affichage et votre mot de passe dans les réglages du compte.`]],["8. Cookies et stockage",["Nous n'utilisons pas de cookies publicitaires ni de mesure d'audience. Le site enregistre votre session et votre choix de langue dans votre navigateur. Cloudflare Turnstile peut utiliser des données strictement nécessaires pour distinguer les personnes des robots."]],["9. Sécurité",["Les connexions sont chiffrées, les mots de passe ne sont jamais stockés en clair, et vous pouvez activer la connexion en deux étapes. Sur votre PC, votre session est chiffrée avec votre compte Windows."]]]},legal:{title:"Mentions légales",lead:"Qui édite ce site et qui l’héberge.",sections:[["Éditeur",[e.name,`Email : ${e.email}`]],["Hébergement",[l]],["Propriété intellectuelle",["Le nom Unlag, son logo, l'application, le site et les textes appartiennent à leur éditeur. Toute reproduction sans autorisation est interdite. Windows est une marque de Microsoft Corporation ; NVIDIA, AMD, Intel, Google et Discord appartiennent à leurs propriétaires. Unlag n'est pas affilié à ces sociétés."]],["Données personnelles",[]]]}}};function a({kind:d}){const i=n()==="fr"?"fr":"en",o=f[i][d];return s.jsxs("main",{children:[s.jsx(m,{title:o.title,children:o.lead}),s.jsx("section",{className:"section section-tight",children:s.jsxs("div",{className:"wrap legal",children:[s.jsx("p",{className:"legal-meta mono",children:u("legal.updated",{date:new Date(h).toLocaleDateString(n(),{day:"numeric",month:"long",year:"numeric"})})}),!["en","fr"].includes(n())&&s.jsx("p",{className:"legal-note",children:u("legal.onlyEnFr")}),o.sections.map(([t,p])=>s.jsxs("section",{className:"legal-block",children:[s.jsx("h2",{children:t}),p.map(r=>s.jsx("p",{children:r},r)),t.startsWith("Personal")||t.startsWith("Données")?s.jsx("p",{children:s.jsx(g,{to:"/privacy",children:i==="fr"?"Politique de confidentialité":"Privacy policy"})}):null]},t))]})})]})}const y=()=>s.jsx(a,{kind:"terms"}),w=()=>s.jsx(a,{kind:"privacy"}),b=()=>s.jsx(a,{kind:"legal"});export{b as LegalNotice,w as Privacy,y as Terms};
